class LRUNode {
  key: number;
  value: number;
  prev: LRUNode | null = null;
  next: LRUNode | null = null;

  constructor(key: number, value: number) {
    this.key = key;
    this.value = value;
  }
}

class LRUCache {
  private capacity: number;
  private map: Map<number, LRUNode>;
  private head: LRUNode; // Most recently used sentinel
  private tail: LRUNode; // Least recently used sentinel

  constructor(capacity: number) {
    if (capacity <= 0) {
      throw new Error("Capacity must be a positive integer");
    }
    this.capacity = capacity;
    this.map = new Map();

    // Initialize dummy head and tail sentinels
    this.head = new LRUNode(0, 0);
    this.tail = new LRUNode(0, 0);
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }

  /**
   * Returns the value associated with the key if it exists,
   * otherwise returns -1. Marks the node as most recently used.
   */
  get(key: number): number {
    const node = this.map.get(key);
    if (!node) return -1;

    // Move to front (most recently used)
    this.moveToFront(node);
    return node.value;
  }

  /**
   * Inserts or updates the key-value pair.
   * Evicts the least recently used item if at capacity.
   */
  put(key: number, value: number): void {
    const existingNode = this.map.get(key);

    if (existingNode) {
      // Update value and move to front
      existingNode.value = value;
      this.moveToFront(existingNode);
    } else {
      // Create new node and add to front
      const newNode = new LRUNode(key, value);
      this.map.set(key, newNode);
      this.addToFront(newNode);

      // Evict LRU item if over capacity
      if (this.map.size > this.capacity) {
        const lruNode = this.removeLRU();
        if (lruNode) {
          this.map.delete(lruNode.key);
        }
      }
    }
  }

  /**
   * Returns current number of entries in the cache.
   */
  size(): number {
    return this.map.size;
  }

  // ── Private helpers ──────────────────────────────────────────────────────

  private addToFront(node: LRUNode): void {
    node.prev = this.head;
    node.next = this.head.next;
    this.head.next!.prev = node;
    this.head.next = node;
  }

  private removeNode(node: LRUNode): void {
    const prevNode = node.prev!;
    const nextNode = node.next!;
    prevNode.next = nextNode;
    nextNode.prev = prevNode;
    node.prev = null;
    node.next = null;
  }

  private moveToFront(node: LRUNode): void {
    this.removeNode(node);
    this.addToFront(node);
  }

  private removeLRU(): LRUNode | null {
    const lruNode = this.tail.prev;
    if (!lruNode || lruNode === this.head) return null;
    this.removeNode(lruNode);
    return lruNode;
  }
}

