### 4.1 CRDT Document Core

```typescript
// shared/crdt-document.ts
import * as Y from 'yjs'
import { Awareness } from 'y-protocols/awareness'

interface DocumentOperation {
  update: Uint8Array      // Binary Yjs state update
  docId: string
  userId: string
  clientId: number
  timestamp: number
  serverTimestamp?: number  // Set by server for ordering/history
}

interface AwarenessState {
  user: {
    id: string
    name: string
    color: string        // Unique per-session color for cursor
    photoUrl?: string
  }
  cursor: {
    anchor: Y.RelativePosition | null  // CRDT-native position (not index!)
    head: Y.RelativePosition | null    // Survives concurrent insertions
  }
  lastActive: number
}

class CRDTDocument {
  public ydoc: Y.Doc
  public awareness: Awareness
  public text: Y.Text
  public metadata: Y.Map<unknown>
  public comments: Y.Array<Y.Map<unknown>>

  constructor(docId: string) {
    this.ydoc = new Y.Doc({ guid: docId })
    this.awareness = new Awareness(this.ydoc)

    // Shared data structures - all CRDT-safe
    this.text = this.ydoc.getText('content')
    this.metadata = this.ydoc.getMap('metadata')
    this.comments = this.ydoc.getArray('comments')
  }

  /**
   * Capture current state as binary snapshot
   * This is idempotent and can be applied multiple times safely
   */
  getStateUpdate(sinceVector?: Uint8Array): Uint8Array {
    if (sinceVector) {
      // Differential update - only what's changed since vector
      const sv = Y.decodeStateVector(sinceVector)
      return Y.encodeStateAsUpdate(this.ydoc, sv)
    }
    return Y.encodeStateAsUpdate(this.ydoc)
  }

  getStateVector(): Uint8Array {
    return Y.encodeStateVector(this.ydoc)
  }

  /**
   * Apply incoming update - CRDT guarantees this is safe
   * regardless of order or duplication
   */
  applyUpdate(update: Uint8Array, origin?: string): void {
    Y.applyUpdate(this.ydoc, update, origin)
  }

  /**
   * Merge two CRDT states - commutative and associative
   * merge(A, B) === merge(B, A) always
   */
  static merge(stateA: Uint8Array, stateB: Uint8Array): Uint8Array {
    const doc = new Y.Doc()
    Y.applyUpdate(doc, stateA)
    Y.applyUpdate(doc, stateB)
    return Y.encodeStateAsUpdate(doc)
  }

  /**
   * CRDT cursor positions survive concurrent edits
   * Unlike index-based positions which shift on insertion
   */
  createRelativeCursorPosition(
    absoluteIndex: number, 
    assoc: -1 | 0 | 1 = 0
  ): Y.RelativePosition {
    const absolutePos = Y.createAbsolutePositionFromRelativePosition(
      Y.createRelativePositionFromTypeIndex(this.text, absoluteIndex, assoc),
      this.ydoc
    )
    return Y.createRelativePositionFromTypeIndex(
      this.text, 
      absolutePos?.index ?? 0, 
      assoc
    )
  }

  resolveRelativeCursorPosition(
    relPos: Y.RelativePosition
  ): number | null {
    const absPos = Y.createAbsolutePositionFromRelativePosition(relPos, this.ydoc)
    return absPos?.index ?? null
  }
}
