### 4.2 WebSocket Server with Room Management

```typescript
// server/websocket-server.ts
import { WebSocketServer, WebSocket } from 'ws'
import { IncomingMessage } from 'http'
import * as Y from 'yjs'
import { encoding, decoding, map } from 'lib0'
import { MessageType, AwarenessMessage } from './protocol'
import { RedisAdapter } from './redis-adapter'
import { PersistenceService } from './persistence'

interface Room {
  docId: string
  ydoc: Y.Doc
  clients: Map<WebSocket, ClientInfo>
  awarenessStates: Map<number, AwarenessState>
  persistenceTimer?: NodeJS.Timer
  lastActivity: number
}

interface ClientInfo {
  userId: string
  clientId: number
  connectedAt: number
}

class CollaborativeWebSocketServer {
  private wss: WebSocketServer
  private rooms: Map<string, Room> = new Map()
  private redis: RedisAdapter
  private persistence: PersistenceService

  // Circuit breaker for overloaded rooms
  private readonly MAX_USERS_PER_DOC = 50
  private readonly ROOM_IDLE_TIMEOUT_MS = 30 * 60 * 1000  // 30 min
  private readonly PERSISTENCE_DEBOUNCE_MS = 2000

  constructor(port: number) {
    this.wss = new WebSocketServer({ port })
    this.redis = new RedisAdapter()
    this.persistence = new PersistenceService()
    this.setupServer()
  }

  private setupServer(): void {
    this.wss.on('connection', this.handleConnection.bind(this))

    // Subscribe to cross-server updates via Redis
    this.redis.subscribe('doc:*:updates', this.handleRedisUpdate.bind(this))
    this.redis.subscribe('doc:*:awareness', this.handleRedisAwareness.bind(this))

    // Cleanup idle rooms
    setInterval(() => this.cleanupIdleRooms(), 60_000)
  }

  private async handleConnection(
    ws: WebSocket, 
    req: IncomingMessage
  ): Promise<void> {
    const { docId, userId, token } = this.parseConnectionParams(req)

    // Authentication check
    if (!await this.validateToken(token, docId)) {
      ws.close(4001, 'Unauthorized')
      return
    }

    let room = this.rooms.get(docId)

    if (!room) {
      room = await this.createRoom(docId)
    }

    if (room.clients.size >= this.MAX_USERS_PER_DOC) {
      ws.close(4029, 'Document at capacity')
      return
    }

    const clientId = this.generateClientId()
    const clientInfo: ClientInfo = { userId, clientId, connectedAt: Date.now() }

    room.clients.set(ws, clientInfo)
    room.lastActivity = Date.now()

    // Step 1: Send current document state to new client
    // This is a differential sync - only send what client is missing
    await this.syncNewClient(ws, room)

    // Step 2: Register message handlers
    ws.on('message', (data: Buffer) => {
      this.handleMessage(ws, room!, data, clientInfo)
    })

    ws.on('close', () => {
      this.handleDisconnect(ws, room!, clientInfo)
    })

    ws.on('error', (err) => {
      console.error(`WS error for user ${userId} in doc ${docId}:`, err)
      this.handleDisconnect(ws, room!, clientInfo)
    })

    // Heartbeat
    this.setupHeartbeat(ws)
  }

  private async createRoom(docId: string): Promise<Room> {
    const ydoc = new Y.Doc({ guid: docId })

    // Load persisted state
    const persistedState = await this.persistence.loadDocument(docId)
    if (persistedState) {
      Y.applyUpdate(ydoc, persistedState)
    }

    const room: Room = {
      docId,
      ydoc,
      clients: new Map(),
      awarenessStates: new Map(),
      lastActivity: Date.now()
    }

    // Listen to CRDT updates, persist with debounce
    ydoc.on('update', (update: Uint8Array, origin: string) => {
      this.onDocumentUpdate(room, update, origin)
    })

    this.rooms.set(docId, room)
    return room
  }

  private async syncNewClient(ws: WebSocket, room: Room): Promise<void> {
    // Send sync step 1: server's state vector
    // Client will respond with what it has that we're missing
    const encoder = encoding.createEncoder()
    encoding.writeVarUint(encoder, MessageType.SYNC_STEP1)
    encoding.writeVarUint8Array(encoder, Y.encodeStateVector(room.ydoc))
    ws.send(encoding.toUint8Array(encoder))
  }

  private handleMessage(
    ws: WebSocket, 
    room: Room, 
    data: Buffer,
    clientInfo: ClientInfo
  ): void {
    const decoder = decoding.createDecoder(new Uint8Array(data))
    const messageType = decoding.readVarUint(decoder)

    switch (messageType) {
      case MessageType.SYNC_STEP1: {
        // Client sent their state vector, we respond with missing updates
        const clientStateVector = decoding.readVarUint8Array(decoder)
        const encoder = encoding.createEncoder()
        encoding.writeVarUint(encoder, MessageType.SYNC_STEP2)
        // Compute differential: only send what client doesn't have
        encoding.writeVarUint8Array(
          encoder,
          Y.encodeStateAsUpdate(room.ydoc, clientStateVector)
        )
        ws.send(encoding.toUint8Array(encoder))
        break
      }

      case MessageType.SYNC_STEP2:
      case MessageType.UPDATE: {
        // Incoming CRDT update from client
        const update = decoding.readVarUint8Array(decoder)

        // Apply to server's document (CRDT: safe to apply in any order)
        Y.applyUpdate(room.ydoc, update, clientInfo.userId)

        // Broadcast to other clients in THIS server's room
        this.broadcastToRoom(room, data, ws)

        // Publish to Redis for OTHER servers' rooms
        this.redis.publish(`doc:${room.docId}:updates`, data)

        room.lastActivity = Date.now()
        break
      }

      case MessageType.AWARENESS: {
        const awarenessUpdate = decoding.readVarUint8Array(decoder)

        // Broadcast awareness (cursors, selections) - ephemeral, not persisted
        this.broadcastToRoom(room, data, ws)
        this.redis.publish(`doc:${room.docId}:awareness`, awarenessUpdate)
        break
      }
    }
  }

  private onDocumentUpdate(
    room: Room, 
    update: Uint8Array, 
    origin: string
  ): void {
    // Debounced persistence - don't write on every keystroke
    clearTimeout(room.persistenceTimer)
    room.persistenceTimer = setTimeout(() => {
      this.persistDocument(room)
    }, this.PERSISTENCE_DEBOUNCE_MS)
  }

  private async persistDocument(room: Room): Promise<void> {
    const state = Y.encodeStateAsUpdate(room.ydoc)
    await this.persistence.saveDocument(room.docId, state)
  }

  private broadcastToRoom(
    room: Room, 
    data: Buffer | Uint8Array, 
    exclude?: WebSocket
  ): void {
    room.clients.forEach((_, client) => {
      if (client !== exclude && client.readyState === WebSocket.OPEN) {
        client.send(data)
      }
    })
  }

  private handleRedisUpdate(channel: string, data: Buffer): void {
    const docId = channel.split(':')[1]
    const room = this.rooms.get(docId)
    if (!room) return  // We don't have this doc loaded

    const update = new Uint8Array(data)

    // Apply to our in-memory doc (CRDT: idempotent, safe)
    Y.applyUpdate(room.ydoc, update, 'redis')

    // Forward to our local WebSocket clients
    this.broadcastToRoom(room, data)
  }

  private handleDisconnect(
    ws: WebSocket, 
    room: Room, 
    clientInfo: ClientInfo
  ): void {
    room.clients.delete(ws)
    room.awarenessStates.delete(clientInfo.clientId)

    // Broadcast awareness removal so cursors disappear
    const awarenessUpdate = encoding.createEncoder()
    // ... encode awareness removal for clientId
    this.broadcastToRoom(room, encoding.toUint8Array(awarenessUpdate))

    // If room is empty, schedule cleanup
    if (room.clients.size === 0) {
      setTimeout(() => {
        if (room.clients.size === 0) {
          this.persistDocument(room).then(() => {
            this.rooms.delete(room.docId)
          })
        }
      }, 5000)  // Wait 5s in case user is refreshing
    }
  }

  private setupHeartbeat(ws: WebSocket): void {
    const interval = setInterval(() => {
      if (ws.readyState === WebSocket.OPEN) {
        ws.ping()
      } else {
        clearInterval(interval)
      }
    }, 30_000)

    ws.on('pong', () => {
      // Connection is alive
    })
  }

  private cleanupIdleRooms(): void {
    const now = Date.now()
    this.rooms.forEach((room, docId) => {
      if (
        room.clients.size === 0 && 
        now - room.lastActivity > this.ROOM_IDLE_TIMEOUT_MS
      ) {
        this.rooms.delete(docId)
      }
    })
  }
}
