### 4.4 Data Persistence Strategy

```typescript
// server/persistence.ts

/**
 * Three-tier persistence strategy:
 * 
 * Tier 1: In-memory Y.Doc (hot, <1ms, lost on restart)
 * Tier 2: Redis cache    (warm, <5ms, survives restarts, TTL 1h)
 * Tier 3: PostgreSQL + S3 (cold, <50ms, permanent)
 */

class PersistenceService {
  private redis: Redis
  private pg: Pool
  private s3: S3Client

  private readonly REDIS_TTL_SECONDS = 3600  // 1 hour
  private readonly SNAPSHOT_INTERVAL_OPS = 1000  // Snapshot every 1K ops
  private readonly MAX_OP_LOG_SIZE = 10_000

  /**
   * Load document: hot path for room creation
   */
  async loadDocument(docId: string): Promise<Uint8Array | null> {
    // Try Redis first (warm cache)
    const cached = await this.redis.getBuffer(`doc:${docId}:state`)
    if (cached) return new Uint8Array(cached)

    // Fall back to PostgreSQL + S3
    const { snapshotKey, opsSinceSnapshot } = await this.pg.query<{
      snapshotKey: string
      opsSinceSnapshot: Buffer[]
    }>(`
      SELECT 
        d.snapshot_s3_key as "snapshotKey",
        ARRAY_AGG(o.update_binary ORDER BY o.server_clock) as "opsSinceSnapshot"
      FROM documents d
      LEFT JOIN document_ops o ON o.doc_id = d.id 
        AND o.server_clock > d.snapshot_at_clock
      WHERE d.id = $1
      GROUP BY d.id, d.snapshot_s3_key
    `, [docId])

    let state: Uint8Array | null = null

    if (snapshotKey) {
      // Load base snapshot from S3
      const snapshot = await this.s3.getObject({ 
        Bucket: 'doc-snapshots', 
        Key: snapshotKey 
      })
      state = new Uint8Array(await snapshot.Body!.transformToByteArray())
    }

    if (opsSinceSnapshot?.length > 0) {
      // Apply incremental ops on top of snapshot
      const doc = new Y.Doc()
      if (state) Y.applyUpdate(doc, state)

      opsSinceSnapshot.forEach(op => {
        Y.applyUpdate(doc, new Uint8Array(op))
      })

      state = Y.encodeStateAsUpdate(doc)
    }

    // Warm the cache
    if (state) {
      await this.redis.setBuffer(
        `doc:${docId}:state`, 
        Buffer.from(state),
        'EX', this.REDIS_TTL_SECONDS
      )
    }

    return state
  }

  /**
   * Save document update - append-only, then snapshot periodically
   */
  async saveDocument(docId: string, fullState: Uint8Array): Promise<void> {
    const client = await this.pg.connect()

    try {
      await client.query('BEGIN')

      // Update Redis cache (fast, always)
      await this.redis.setBuffer(
        `doc:${docId}:state`,
        Buffer.from(fullState),
        'EX', this.REDIS_TTL_SECONDS
      )

      // Get operation count since last snapshot
      const { rows } = await client.query(`
        SELECT ops_since_snapshot, snapshot_at_clock
        FROM documents WHERE id = $1 FOR UPDATE
      `, [docId])

      const opCount = rows[0]?.ops_since_snapshot ?? 0

      if (opCount >= this.SNAPSHOT_INTERVAL_OPS) {
        // Time to take a full snapshot - upload to S3
        const snapshotKey = `${docId}/snapshot-${Date.now()}.bin`

        await this.s3.putObject({
          Bucket: 'doc-snapshots',
          Key: snapshotKey,
          Body: Buffer.from(fullState),
          ContentType: 'application/octet-stream'
        })

        // Update snapshot reference, reset counter
        await client.query(`
          UPDATE documents 
          SET snapshot_s3_key = $2,
              snapshot_at_clock = current_clock,
              ops_since_snapshot = 0,
              updated_at = NOW()
          WHERE id = $1
        `, [docId, snapshotKey])

        // Prune old ops (they're now baked into snapshot)
        await client.query(`
          DELETE FROM document_ops 
          WHERE doc_id = $1 
          AND server_clock <= (SELECT snapshot_at_clock FROM documents WHERE id = $1)
        `, [docId])

      } else {
        // Just increment counter
        await client.query(`
          UPDATE documents 
          SET ops_since_snapshot = ops_since_snapshot + 1,
              updated_at = NOW()
          WHERE id = $1
        `, [docId])
      }

      await client.query('COMMIT')

    } catch (err) {
      await client.query('ROLLBACK')
      throw err
    } finally {
      client.release()
    }
  }

  /**
   * Version history - point-in-time recovery
   */
  async getDocumentAtTime(
    docId: string, 
    timestamp: Date
  ): Promise<Uint8Array | null> {
    // Find snapshot before timestamp
    const { rows } = await this.pg.query(`
      SELECT snapshot_s3_key, snapshot_at_clock
      FROM document_snapshots
      WHERE doc_id = $1 AND created_at <= $2
      ORDER BY created_at DESC LIMIT 1
    `, [docId, timestamp])

    if (!rows[0]) return null

    // Load snapshot
    const snapshot = await this.s3.getObject({
      Bucket: 'doc-snapshots',
      Key: rows[0].snapshot_s3_key
    })
    let state = new Uint8Array(await snapshot.Body!.transformToByteArray())

    // Apply ops up to timestamp
    const ops = await this.pg.query(`
      SELECT update_binary FROM document_ops
      WHERE doc_id = $1
      AND server_clock > $2
      AND created_at <= $3
      ORDER BY server_clock ASC
    `, [docId, rows[0].snapshot_at_clock, timestamp])

    if (ops.rows.length > 0) {
      const doc = new Y.Doc()
      Y.applyUpdate(doc, state)
      ops.rows.forEach(({ update_binary }) => {
        Y.applyUpdate(doc, new Uint8Array(update_binary))
      })
      state = Y.encodeStateAsUpdate(doc)
    }

    return state
  }
}
