## 6. Database Schema

```sql
-- Documents table
CREATE TABLE documents (
  id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  title               VARCHAR(500),
  owner_id            UUID REFERENCES users(id),
  snapshot_s3_key     VARCHAR(500),     -- Latest S3 snapshot path
  snapshot_at_clock   BIGINT DEFAULT 0, -- Server clock at snapshot time
  ops_since_snapshot  INTEGER DEFAULT 0,-- Counter for snapshot trigger
  current_clock       BIGINT DEFAULT 0, -- Lamport clock
  word_count          INTEGER,          -- Denormalized for perf
  created_at          TIMESTAMPTZ DEFAULT NOW(),
  updated_at          TIMESTAMPTZ DEFAULT NOW()
);

-- Operation log (append-only, partitioned by time)
CREATE TABLE document_ops (
  id            BIGSERIAL,
  doc_id        UUID REFERENCES documents(id),
  user_id       UUID REFERENCES users(id),
  client_id     INTEGER,              -- Yjs client ID
  update_binary BYTEA NOT NULL,       -- Binary Yjs update
  server_clock  BIGINT NOT NULL,      -- Server-assigned clock
  client_clock  INTEGER,             -- Client's Yjs clock
  byte_length   INTEGER,
  created_at    TIMESTAMPTZ DEFAULT NOW(),
  PRIMARY KEY (id, created_at)
) PARTITION BY RANGE (created_at);

-- Create monthly partitions
CREATE TABLE document_ops_2024_01 
  PARTITION OF document_ops
  FOR VALUES FROM ('2024-01-01') TO ('2024-02-01');

-- Snapshot history (for version restore)
CREATE TABLE document_snapshots (
  id             BIGSERIAL PRIMARY KEY,
  doc_id         UUID REFERENCES documents(id),
  snapshot_s3_key VARCHAR(500),
  clock_at_snapshot BIGINT,
  byte_length    INTEGER,
  created_by     UUID REFERENCES users(id),
  label          VARCHAR(200),  -- Optional user-named version
  created_at     TIMESTAMPTZ DEFAULT NOW()
);

-- Access control
CREATE TABLE document_permissions (
  doc_id  UUID REFERENCES documents(id),
  user_id UUID REFERENCES users(id),
  role    VARCHAR(20) CHECK (role IN ('owner', 'editor', 'commenter', 'viewer')),
  PRIMARY KEY (doc_id, user_id)
);

-- Indices for hot paths
CREATE INDEX idx_doc_ops_doc_clock ON document_ops(doc_id, server_clock);
CREATE INDEX idx_doc_ops_created ON document_ops(doc_id, created_at);
CREATE INDEX idx_permissions_user ON document_permissions(user_id);
